import zlib,struct,numpy as np
def load(fn):
    d=open(fn,'rb').read()
    i=8; idat=b''; W=H=bd=ct=None; pal=None
    while i<len(d):
        ln=struct.unpack('>I',d[i:i+4])[0]; typ=d[i+4:i+8]; data=d[i+8:i+8+ln]; i+=12+ln
        if typ==b'IHDR':
            W,H,bd,ct=struct.unpack('>IIBB',data[:10])
        elif typ==b'IDAT': idat+=data
        elif typ==b'PLTE': pal=np.frombuffer(data,dtype=np.uint8).reshape(-1,3)
        elif typ==b'IEND': break
    raw=zlib.decompress(idat)
    nch={0:1,2:3,3:1,4:2,6:4}[ct]
    stride=W*nch
    out=np.zeros((H,stride),dtype=np.uint8)
    prev=np.zeros(stride,dtype=np.uint8)
    pos=0
    for y in range(H):
        f=raw[pos]; pos+=1
        line=np.frombuffer(raw[pos:pos+stride],dtype=np.uint8).copy(); pos+=stride
        if f==1:
            for x in range(nch,stride): line[x]=(line[x]+line[x-nch])&255
        elif f==2:
            line=(line+prev)&255
        elif f==3:
            for x in range(stride):
                a=line[x-nch] if x>=nch else 0
                line[x]=(line[x]+((int(a)+int(prev[x]))>>1))&255
        elif f==4:
            for x in range(stride):
                a=line[x-nch] if x>=nch else 0
                b=prev[x]; c=prev[x-nch] if x>=nch else 0
                p=int(a)+int(b)-int(c)
                pa=abs(p-a);pb=abs(p-b);pc=abs(p-c)
                pr=a if (pa<=pb and pa<=pc) else (b if pb<=pc else c)
                line[x]=(line[x]+pr)&255
        out[y]=line; prev=line
    if ct==3:
        return pal[out.reshape(H,W)]
    if ct==6:
        return out.reshape(H,W,4)[:,:,:3]
    if ct==2:
        return out.reshape(H,W,3)
    return out.reshape(H,W)
